function renderProgress(){let d=state.imed.find(x=>x.id===state.currentDoc);if(!d)return;const auto=allAutoRows.find(x=>String(x.d?.id)===String(d.id));let t=target(d),s=auto?num(auto.total):totalAllocated(d.id),p=t?Math.min(100,s/t*100):0;$('qtyProgress').style.width=p+'%';$('qtyProgressText').innerHTML=`مقدار پوشش‌داده‌شده: <b>${faNum(s)}</b> از <b>${faNum(t)}</b> — ${statusTag(dashboardDocStatus(d))}`;$('reconcileStatus').innerHTML=statusMessage(d)}
function statusMessage(d){let t=target(d),auto=allAutoRows.find(x=>String(x.d?.id)===String(d.id)),s=auto?num(auto.total):totalAllocated(d.id);if(!t)return'<div class="notice bad">مقدار هدف این سند خالی یا صفر است. ستون «تعداد توزیع» را در فایل IMED بررسی کنید.</div>';if(auto&&auto.status==='کامل')return`<div class="notice good">موتور تطبیق برای این سند پیشنهاد کامل پیدا کرده است: ${faNum(s)} از ${faNum(t)} واحد. پیشنهادها هنوز در تخصیص‌های ذخیره‌شده ثبت نشده‌اند.</div>`;if(auto&&auto.planned?.length)return`<div class="notice info">موتور تطبیق ${faNum(auto.got)} واحد پیشنهاد داده است؛ ${faNum(auto.left)} واحد باقی مانده. پیشنهادها را در جدول جامع بررسی کن.</div>`;if(Math.abs(s-t)<.00001&&allocationsFor(d.id).length)return`<div class="notice good">جمع تخصیص‌های ذخیره‌شده دقیقاً با مقدار توزیع برابر است: ${faNum(t)} واحد.</div>`;if(s>t)return`<div class="notice bad">مقدار تخصیص‌یافته ${faNum(s-t)} واحد بیشتر از مقدار توزیع است. تخصیص‌ها را اصلاح کنید.</div>`;return`<div class="notice warn">هنوز ${faNum(t-s)} واحد تا تکمیل مقدار توزیع باقی مانده است. ردیف‌های فاکتور بیشتری اضافه کنید یا مقدار تخصیص‌ها را اصلاح کنید.</div>`}
