 const used=new Map();Object.values(state.allocations||{}).forEach(list=>(list||[]).forEach(a=>{const k=String(a.sourceId);used.set(k,(used.get(k)||0)+num(a.allocatedQty))}));
 const pool=indexedSepidarCandidates(d,$('productMatch')?.value||'auto',invoiceNums()).map(s=>{const free=Math.max(0,num(s.quantity)-(used.get(String(s.id))||0));return{s,free,...matchSignals(d,s,free)}})
