 if(!pool.length){$('candidateResults').innerHTML='<div class="notice warn">با معیارهای فعلی فاکتور مناسبی پیدا نشد. جست‌وجوی دستی را اجرا کن یا نام کالا، IRC، تاریخ و مقدار را کنترل کن.</div>';return toast('فاکتور واجد شرایط پیدا نشد')}
 let planned=[],left=needed;for(const c of pool){if(left<=0)break;const q=Math.min(left,c.free);if(q>0){planned.push({c,q});left-=q}}
