       const wb=XLSX.read(ab,{type:'array',cellDates:false});let best={score:0};
       for(const sn of wb.SheetNames){const mat=XLSX.utils.sheet_to_json(wb.Sheets[sn],{header:1,defval:'',raw:false});for(let ri=0;ri<Math.min(mat.length,15);ri++){const h=(mat[ri]||[]).map(x=>String(x??'').trim()),found={};for(const [key,alts] of Object.entries(aliases)){const pos=h.findIndex(cell=>alts.some(a=>hn(cell)===hn(a)||hn(cell).includes(hn(a))));if(pos>=0)found[key]=pos}const score=Object.keys(found).length+(found.inventoryId!==undefined?3:0)+(found.irc!==undefined?3:0)+(found.remainingQty!==undefined?3:0);if(score>best.score)best={score,sn,mat,ri,found}}}
