function resolveStock(d,a,used={}){const c=stockCandidates(d,a);const ok=v=>num(v.remainingQty)-num(used[v.inventoryId]||0)>=num(a.allocatedQty);if(a.inventoryId){const v=c.find(x=>String(x.inventoryId)===String(a.inventoryId));if(v&&ok(v))return{row:v,reason:'انتخاب‌شده'};return{row:null,reason:'InventoryID انتخاب‌شده موجودی کافی ندارد یا در Snapshot نیست'}}const eligible=c.filter(ok);const exact=eligible.filter(v=>Math.abs(num(v.remainingQty)-num(used[v.inventoryId]||0)-num(a.allocatedQty))<0.00001);if(exact.length===1)return{row:exact[0],reason:'تطبیق یکتای مقدار با باقیمانده'};if(exact.length>1)return{row:null,reason:'چند InventoryID با باقیمانده برابر پیدا شد؛ انتخاب دستی لازم است'};if(eligible.length===1)return{row:eligible[0],reason:'تنها InventoryID دارای موجودی کافی'};if(!eligible.length)return{row:null,reason:c.length?'موجودی باقیمانده کافی نیست':'IRC در Snapshot انبار پیدا نشد'};return{row:null,reason:'چند InventoryID موجودی کافی دارند؛ انتخاب دستی لازم است'}}
function renderXmlRows(){const did=$('xmlDocSelect')?.value,d=state.imed.find(x=>x.id===did);if(!d||!$('xmlRecordsTable'))return;const alloc=allocationsFor(d.id);if(!alloc.length){$('xmlRecordsTable').innerHTML='<div class="empty">برای این سند هنوز فاکتور فروش سپیدار تخصیص داده نشده است.</div>';$('xmlValidation').innerHTML='';return}let used={},rows=[];for(const a of alloc){const r=resolveStock(d,a,used);const stock=r.row;if(stock)used[stock.inventoryId]=(used[stock.inventoryId]||0)+num(a.allocatedQty);rows.push({a,stock,reason:r.reason,candidates:stockCandidates(d,a)})} $('xmlRecordsTable').innerHTML=`<div class="section-head"><div><h2>تخصیص‌ها و انتخاب موجودی مجازی</h2><p>برای هر ردیف، موجودی فقط از IRC همان کالا در Snapshot گرفته می‌شود.</p></div><span class="tag neutral">${faNum(alloc.length)} ردیف</span></div><div class="table-wrap"><table><thead><tr><th>فاکتور فروش</th><th>تاریخ</th><th>تعداد XML</th><th>فی</th><th>InventoryID از IMED</th><th>وضعیت</th></tr></thead><tbody>${rows.map(({a,stock,reason,candidates})=>`<tr><td>${esc(a.invoiceNo)}</td><td>${esc(a.invoiceDate||'—')}</td><td>${faNum(a.allocatedQty)}</td><td>${money(a.unitPrice)}</td><td><select data-stockalloc="${a.id}" style="min-width:230px;padding:7px;border:1px solid var(--line);border-radius:7px"><option value="">انتخاب دستی / نامشخص</option>${candidates.map(v=>`<option value="${esc(v.inventoryId)}" ${String(a.inventoryId||stock?.inventoryId||'')===String(v.inventoryId)?'selected':''}>${esc(v.inventoryId)} — مانده ${faNum(v.remainingQty)} — ${esc(v.product||'')}</option>`).join('')}</select></td><td>${stock?'<span class="tag good">قابل استفاده</span>':`<span class="tag warn">${esc(reason)}</span>`}</td></tr>`).join('')}</tbody></table></div>`;$('xmlRecordsTable').querySelectorAll('[data-stockalloc]').forEach(sel=>sel.onchange=()=>{const a=alloc.find(x=>x.id===sel.dataset.stockalloc);if(a){a.inventoryId=sel.value;save();renderXmlRows()}});validateXmlDoc(d,false)}
function makeQuotaRows(d,checkXmlTotal=true,forForm=false){let used={},rows=[],errors=[],skipped=[];if(!d)return{rows,errors:['سندی انتخاب نشده است']};const autoRow=allAutoRows.find(x=>String(x.d?.id)===String(d.id));const savedAllocations=allocationsFor(d.id);const proposedAllocations=autoRow?(autoRow.planned||[]).filter(p=>num(p.q)>0&&p.s).map(p=>({sourceId:p.s.id,allocatedQty:num(p.q),invoiceNo:p.s.invoiceNo,invoiceDate:p.s.invoiceDate,customer:p.s.customer,product:p.s.product,irc:p.s.irc,unitPrice:p.s.unitPrice,signals:p.signals||[],score:p.score})):[];/* تطبیق ناقص به‌تنهایی مانع ساخت اسکریپت ثبت نیست؛ فقط ردیف‌های پیشنهادی با تعداد مثبت ارسال می‌شوند. */const allocationKey=a=>a.sourceId?'id:'+String(a.sourceId):'invoice:'+norm(a.invoiceNo)+'|'+norm(a.invoiceDate)+'|'+norm(a.product);const savedKeys=new Set(savedAllocations.map(allocationKey));const pendingProposals=proposedAllocations.filter(a=>!savedKeys.has(allocationKey(a)));const docAllocations=[...savedAllocations,...pendingProposals];const rawTypeId=String(d.typeId||'').trim();const mappedTypeId=inferTypeId(d);const typeId=rawTypeId||mappedTypeId;const receiverCode=String(d.receiverCode||'').trim();if(rawTypeId&&mappedTypeId&&rawTypeId!==mappedTypeId)errors.push(`TypeID ذخیره‌شده (${rawTypeId}) با نوع توزیع «${d.distributionType||'—'}» و نگاشت مرجع (${mappedTypeId}) مغایرت دارد.`);for(const a of docAllocations){const r=forForm?{row:null,reason:'فیلدهای درخواستی خالی گذاشته شدند'}:resolveStock(d,a,used);const inv=r.row;const row={TypeID:typeId,IRC:String(d.irc||a.irc||''),Count:num(a.allocatedQty),RialPrice:num(a.unitPrice),InvoiceNo:String(a.invoiceNo||''),InvoiceDate:String(a.invoiceDate||''),InventoryID:forForm?'':(inv?String(inv.inventoryId):String(a.inventoryId||'')),ReceiverCode:forForm?'':receiverCode,ReceiverName:forForm?'':String(d.receiver||'')};let miss=[];const required=forForm?['TypeID','IRC','Count','RialPrice','InvoiceNo','InvoiceDate']:['TypeID','IRC','Count','RialPrice','InvoiceNo','InvoiceDate','InventoryID','ReceiverCode','ReceiverName'];for(const k of required){if(row[k]===''||row[k]===0||row[k]==null)miss.push(k)}if(!forForm&&!inv)miss.push('InventoryID/موجودی قابل تأیید');if(inv)used[inv.inventoryId]=(used[inv.inventoryId]||0)+row.Count;if(miss.length){const message=`فاکتور ${row.InvoiceNo||'؟'}: فیلدهای ضروری ناقص یا نامعتبر: ${[...new Set(miss)].join('، ')} (${r.reason})`;errors.push(message);continue}else rows.push(row)}const total=rows.reduce((s,x)=>s+x.Count,0);if(checkXmlTotal&&Math.abs(total-num(d.quantity))>0.00001)skipped.push(`تطبیق ناقص: تعداد تخصیص‌یافته ${faNum(total)} از مقدار سند IMED (${faNum(d.quantity)}) کمتر/بیشتر است؛ XML با مقدار واقعی تخصیص‌یافته ساخته می‌شود.`);if(!docAllocations.length)errors.push('هیچ فاکتور فروشی به این سند تخصیص داده نشده یا پیشنهاد تطبیقی محاسبه نشده است.');if(forForm&&!rows.length&&!errors.length)errors.push('هیچ ردیفی با فیلدهای اجباری کافی برای ارسال به فرم IMED باقی نماند.');return{rows,errors,total,skipped}}
function xmlEsc(s){return String(s??'').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;').replace(/'/g,'&apos;')}
function quotaXml(rows){return `<?xml version="1.0" encoding="UTF-8"?>\n<QuotaList>\n${rows.map(r=>'  <Quota>\n'+Object.entries(r).map(([k,v])=>`    <${k}>${xmlEsc(v)}</${k}>`).join('\n')+'\n  </Quota>').join('\n')}\n</QuotaList>\n`}
