function autoColumn(headers,alts){let nh=headers.map(h=>norm(h));for(let a of alts){let n=norm(a),idx=nh.findIndex(h=>h===n||h.includes(n));if(idx>=0)return idx}return -1}
function buildMapping(){let mode=$('importMode').value,defs=fields[mode],headers=activeMatrix[0]||[];const saved=state.importSources?.[mode]?.map||{};let opts='<option value="">— انتخاب نشده —</option>'+columnOptions().map(o=>`<option value="${o.i}">${esc(o.label)}</option>`).join('');$('mappingGrid').innerHTML=defs.map(([key,label,alts])=>{let v=Number.isInteger(saved[key])?saved[key]:autoColumn(headers,alts);return `<div class="field"><label>${label}</label><select data-map="${key}">${opts}</select></div>`}).join('');$('mappingGrid').querySelectorAll('[data-map]').forEach(sel=>{let def=defs.find(x=>x[0]===sel.dataset.map);let v=Number.isInteger(saved[def[0]])?saved[def[0]]:autoColumn(headers,def[2]);sel.value=v>=0?String(v):''});$('mappingArea').classList.remove('hidden');$('previewArea').classList.add('hidden');$('sourceRows').textContent=faNum(Math.max(0,activeMatrix.length-1))+' ردیف'}
